const body = $input.first().json.body || $input.first().json || {};

// Handle both project_v2_item events and issue events
const action = body.action || '';
const projectItem = body.projects_v2_item || {};
const issue = body.issue || {};
const comment = body.comment || {};

// Determine column from project card event OR issue label
let column = 'unknown';
if (projectItem.column_name) {
  column = projectItem.column_name.trim();
} else if (action === 'labeled') {
  column = 'Ready';
} else if (action === 'created' && comment.id) {
  column = 'comment'; // issue comment — human reply path
}

const issueNumber = issue.number || projectItem.content_number || 0;
const issueTitle = issue.title || projectItem.content_title || `Issue #${issueNumber}`;
const issueBody = issue.body || 'No description provided.';
const commentBody = comment.body || '';
const sender = body.sender?.login || '';

// A human reply is a comment NOT from a bot or automation
const isHumanReply = (
  column === 'comment' &&
  commentBody.length > 0 &&
  !sender.includes('[bot]') &&
  !sender.includes('n8n') &&
  !sender.includes('aider')
);

return [{
  json: {
    column,
    issueNumber,
    issueTitle,
    issueBody,
    commentBody,
    sender,
    isHumanReply,
    repo: body.repository?.full_name || 'conarwelsh/sous.tools'
  }
}];

// Check if aider output a NEEDS_INPUT signal
const output = $input.first().json.stdout || '';
const needsInput = output.includes('NEEDS_INPUT:');
let question = '';
if (needsInput) {
  const match = output.match(/NEEDS_INPUT:\s*(.+)/);
  question = match ? match[1].trim() : 'Agent needs additional information to proceed.';
}
return [{ json: { ...$input.first().json, needsInput, agentQuestion: question } }];

